import { mainAuth } from "./auth"
import { Request, Response, NextFunction } from 'express';


export const checkAuth = (req: Request, res: Response, next: NextFunction) =&gt; { 
    let authToken = req.headers.authorization
    if (!!authToken) {
        authToken = authToken.split(' ')[1]
        if (mainAuth(authToken)) {
            next()
        } else {
            res.status(401).json({error: 'Ошибка авторизации'})
        }
    } else {
        res.status(401).json({error: 'Ошибка авторизации'})
    }
}

import crypto from 'crypto'

export const mainAuth = (token: string) =&gt; {
    if (token === crypto.createHash('sha256').update('bvcxertyuiolkmnbvedhklcvb').digest('hex')) {
        return true
    } else {
        return false
    }
}

