                `SELECT "geo.resp.country_code" AS country, COUNT(*) AS count, "geo.resp.latitude" AS lat, "geo.resp.longitude" AS lon
                FROM conn
                WHERE country IS NOT NULL AND
                ts &gt;= ? AND ts &lt;= ? AND
                "id.orig_h" = ?
                GROUP BY country
                ORDER BY count DESC;`,
                [timeStart, timeEnd, clientIp]
            )

            if (clientRole === 'node') {
                const clientDependResp = await getQuery&lt;{
                    id: number
                }&gt;(
                    db,
                    'SELECT admin_id as id FROM node_depends WHERE node_id = ?',
                    [clientId]
                )

                adminId = clientDependResp[0].id
            }

            let blackListCountriesResp = await getQuery&lt;{
                countries: string
            }&gt;(
                db,
                'SELECT countries_codes AS countries FROM block_countries WHERE clientId = ?',
                [!!adminId ? adminId : clientId]
            )

            let blackListCountries = blackListCountriesResp.reduce((acc, cur) =&gt; acc + ',' + cur.countries, '')

            const blacklistSet = new Set(
                blackListCountries
                    ? blackListCountries.split(',').map(code =&gt; code.trim().toUpperCase()).filter(Boolean)
                    : []
            );

            const enriched = countries?.map(item =&gt; ({
                ...item,
                blackList: blacklistSet.has(item.country.toUpperCase())
            }));

            db.close()

            res.json({
                success: true,
                info: {
                    countries: enriched
                }
            })
        } else {
            db.close()

            res.json({
                success: true,
                info: {
                    countries: []
                }
            })
        }
    } catch (e) {
        db.close()

        res.json({
            success: false,
            info: String(e) || 'Произошла непредвиденная ошибка'
        })
    }
}

import { createDb, getQuery } from "../../db/queryDb";
import { Response, Request } from "express";
import { FilterViewType, RequestConnectionInfoParamsType } from "../../types/connections";

const DEFAULT_TZ_OFFSET_SEC = 3 * 3600;

function formatLabelView(ts: number, view: FilterViewType, tzOffsetSec: number) {
    const d = new Date((ts + tzOffsetSec) * 1000);
    switch (view) {
        case "hour":
        case "6hour":
        case "12hour": {
            const h = d.getUTCHours().toString().padStart(2, "0");
            const m = d.getUTCMinutes().toString().padStart(2, "0");
            return `${h}:${m}`;
        }
        case "day": {
            return `${d.getUTCHours().toString().padStart(2, "0")}:00`;
        }
        case "week": {
            const days = ["ПН", "ВТ", "СР", "ЧТ", "ПТ", "СБ", "ВС"];
            return days[(d.getUTCDay() + 6) % 7];
        }
        case "month": {
            return d.getUTCDate().toString().padStart(2, "0");
        }
        default:
            return "";
    }
}

function formatLabelCustom(ts: number, bucketSize: number, tzOffsetSec: number) {
    const d = new Date((ts + tzOffsetSec) * 1000);
    if (bucketSize &lt; 3600) {
        const h = d.getUTCHours().toString().padStart(2, "0");
        const m = d.getUTCMinutes().toString().padStart(2, "0");
        return `${h}:${m}`;
    } else if (bucketSize === 3600) {
        return `${d.getUTCHours().toString().padStart(2, "0")}:00`;
    } else {
        return d.toISOString().slice(0, 10); // YYYY-MM-DD
    }
}

function generateTitle(
    view: FilterViewType,
    startUnix: number,
    endUnix: number,
    tzOffsetSec: number
) {
    const start = new Date((startUnix + tzOffsetSec) * 1000);
    const end = new Date((endUnix + tzOffsetSec) * 1000);

    const pad = (n: number) =&gt; n.toString().padStart(2, "0");
    const fmtTime = (d: Date) =&gt; `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`;
    const fmtDate = (d: Date) =&gt;
        `${pad(d.getUTCDate())}.${pad(d.getUTCMonth() + 1)}.${d.getUTCFullYear()}`;

    const monthNames = [
        "Январь", "Февраль", "Март", "Апрель", "Май", "Июнь",
        "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь"
    ];

    switch (view) {
        case "hour":
        case "6hour":
        case "12hour":
            return `С ${fmtTime(start)} до ${fmtTime(end)} ${fmtDate(start)}`;
        case "day":
            return fmtDate(start);
        case "week": {
            const endOfWeek = new Date((endUnix + tzOffsetSec - 1) * 1000);
            return `Неделя ${fmtDate(start)} – ${fmtDate(endOfWeek)}`;
        }
        case "month": {
            const year = start.getUTCFullYear();
            const month = monthNames[start.getUTCMonth()];
            return `${month} ${year}`;
        }
        case "custom": {
            const diffSec = endUnix - startUnix;
            if (diffSec &lt;= 86400 && start.getUTCDate() === end.getUTCDate()) {
                return `С ${fmtTime(start)} до ${fmtTime(end)} ${fmtDate(start)}`;
            } else {
                return `С ${fmtDate(start)} ${fmtTime(start)} до ${fmtDate(end)} ${fmtTime(end)}`;
            }
        }
        default:
            return "";
    }
}

const aggregate = (
    rows: any[],
    bucketList: {
        ts: number;
        label: string;
        value: number;
    }[],
    bucketSize: number,
    anchorStart: number
) =&gt; {
    const result = bucketList.map((b) =&gt; ({ ...b }));
    const map = new Map(result.map((b) =&gt; [b.ts, b]));
    for (const row of rows) {
        const key = anchorStart + Math.floor((row.ts - anchorStart) / bucketSize) * bucketSize;
        const entry = map.get(key);
        if (entry) {
            entry.value += row.bytes;
        }
    }
    return result;
};

const getConnectionInfo = async (req: Request, res: Response) =&gt; {
    const {
        clientId,
        selectedView,
        timeStart,
        timeEnd,
        offset,
        dateNow
    }: RequestConnectionInfoParamsType = req.body;

    const tzOffsetSec =
        req.body.tzOffsetSec !== undefined ? Number(req.body.tzOffsetSec) : DEFAULT_TZ_OFFSET_SEC;

    const db = createDb(res);

    try {
        const ipResponse = await getQuery&lt;{ ipAddr: string }&gt;(
            db,
            "SELECT ip_addr as ipAddr FROM vpn_users WHERE id = ?",
            [clientId]
        );

        const clientIp: undefined | string = ipResponse[0]?.ipAddr;

        const parsedDate = typeof dateNow === "number" ? dateNow : new Date(dateNow).getTime();
        const nowSec = parsedDate &gt; 1e12 ? Math.floor(parsedDate / 1000) : Math.floor(parsedDate);
        const off = Number(offset) || 0;

        let intervalStart: number;
        let intervalEnd: number;
        let bucketSize: number;
        let buckets: { ts: number; label: string; value: number }[];
        let anchorStart: number;

        if (selectedView === "custom") {
            intervalStart = timeStart;
            intervalEnd = timeEnd;
            const duration = intervalEnd - intervalStart;
            if (duration &lt;= 3600) bucketSize = 600;
            else if (duration &lt;= 21600) bucketSize = 900;
            else if (duration &lt;= 43200) bucketSize = 1800;
            else if (duration &lt;= 86400) bucketSize = 3600;
            else bucketSize = 86400;

            anchorStart =
                Math.floor((intervalStart + tzOffsetSec) / bucketSize) * bucketSize - tzOffsetSec;
            buckets = [];
            for (let t = anchorStart; t &lt; intervalEnd; t += bucketSize) {
                buckets.push({
                    ts: t,
                    label: formatLabelCustom(t, bucketSize, tzOffsetSec),
                    value: 0
                });
            }
        } else {
            switch (selectedView) {
                case "hour":
                    intervalStart = Math.floor(nowSec / 3600) * 3600 - off * 3600;
                    intervalEnd = intervalStart + 3600;
                    bucketSize = 600;
                    break;
                case "6hour":
                    intervalStart =
                        Math.floor((nowSec + tzOffsetSec) / 21600) * 21600 -
                        tzOffsetSec -
                        off * 21600;
                    intervalEnd = intervalStart + 21600;
                    bucketSize = 900;
                    break;
                case "12hour":
                    intervalStart =
                        Math.floor((nowSec + tzOffsetSec) / 43200) * 43200 -
                        tzOffsetSec -
                        off * 43200;
                    intervalEnd = intervalStart + 43200;
                    bucketSize = 1800;
                    break;
                case "day":
                    intervalStart =
                        Math.floor((nowSec + tzOffsetSec) / 86400) * 86400 -
                        tzOffsetSec -
                        off * 86400;
                    intervalEnd = intervalStart + 86400;
                    bucketSize = 3600;
                    break;
                case "week": {
                    const d = new Date((nowSec + tzOffsetSec) * 1000);
                    const dayOfWeek = d.getUTCDay();
                    const diffToMonday = (dayOfWeek + 6) % 7;
                    const monday =
                        Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() - diffToMonday) /
                        1000;
                    intervalStart = monday - tzOffsetSec - off * 7 * 86400;
                    intervalEnd = intervalStart + 7 * 86400;
                    bucketSize = 86400;
                    break;
                }
                case "month": {
                    const d = new Date((nowSec + tzOffsetSec) * 1000);
                    const year = d.getUTCFullYear();
                    const month = d.getUTCMonth();
                    const totalMonths = year * 12 + month - off;
                    const targetYear = Math.floor(totalMonths / 12);
                    const targetMonth = totalMonths % 12;
                    intervalStart = Date.UTC(targetYear, targetMonth, 1) / 1000 - tzOffsetSec;
                    intervalEnd = Date.UTC(targetYear, targetMonth + 1, 1) / 1000 - tzOffsetSec;
                    bucketSize = 86400;
                    break;
                }
                default:
                    return res
                        .status(400)
                        .json({ error: `Неподдерживаемый selectedView: ${selectedView}` });
            }

            anchorStart = intervalStart;
            buckets = [];
            for (let t = intervalStart; t &lt; intervalEnd; t += bucketSize) {
                buckets.push({
                    ts: t,
                    label: formatLabelView(t, selectedView, tzOffsetSec),
                    value: 0
                });
            }
        }

        const title = generateTitle(selectedView, intervalStart, intervalEnd, tzOffsetSec);

        const [origRows, respRows] = await Promise.all([
            getQuery(
                db,
                `SELECT ts, orig_bytes AS bytes FROM conn WHERE "id.orig_h" = ? AND ts BETWEEN ? AND ?
                UNION ALL
                SELECT ts, resp_bytes AS bytes FROM conn WHERE "id.resp_h" = ? AND ts BETWEEN ? AND ?`,
                [clientIp, intervalStart, intervalEnd, clientIp, intervalStart, intervalEnd]
            ),
            getQuery(
                db,
                `SELECT ts, resp_bytes AS bytes FROM conn WHERE "id.orig_h" = ? AND ts BETWEEN ? AND ?
                UNION ALL
                SELECT ts, orig_bytes AS bytes FROM conn WHERE "id.resp_h" = ? AND ts BETWEEN ? AND ?`,
                [clientIp, intervalStart, intervalEnd, clientIp, intervalStart, intervalEnd]
            )
        ]);

        const respPoints = aggregate(respRows, buckets, bucketSize, anchorStart);
        const origPoints = aggregate(origRows, buckets, bucketSize, anchorStart);

        const sumRespBytes = respPoints.reduce((acc, cur) =&gt; cur.value + acc, 0);
        const sumOrigBytes = origPoints.reduce((acc, cur) =&gt; cur.value + acc, 0);

        return res.json({
            success: true,
            title,
            info: {
                resp: {
                    points: respPoints,
                    max: Math.max(...respPoints.map((item) =&gt; item.value)),
                    min: Math.min(...respPoints.map((item) =&gt; item.value)),
                    sum: sumRespBytes
                },
                orig: {
                    points: origPoints,
                    max: Math.max(...origPoints.map((item) =&gt; item.value)),
                    min: Math.min(...origPoints.map((item) =&gt; item.value)),
                    sum: sumOrigBytes
                }
            }
        });
    } catch (e) {
        return res.json({ success: false, info: e });
    } finally {
        db.close();
    }
};

export default getConnectionInfo;

import {Response, Request} from 'express'
import { createDb, getQuery } from '../../db/queryDb'
import { UserRoleType } from '../../types/user';

type GetSslTopParamsType = {
    timeStart: number,
    timeEnd: number,
    limit: number,
    clientId: number
}

export const getSslTop = async (req: Request, res: Response) =&gt; {
    let adminId: null | number = null;
    const {
        timeStart,
        timeEnd,
        limit,
        clientId
    }: GetSslTopParamsType = req.body

    const db = createDb(res)

    try {
        const clientInfoResp = await getQuery&lt;{
            clientIp: string,
            role: UserRoleType
        }&gt;(
            db,
            'SELECT ip_addr as clientIp, role FROM vpn_users WHERE id = ?',
            [clientId]
        )

        const clientIp: undefined | string = clientInfoResp[0]?.clientIp
        const clientRole: UserRoleType = clientInfoResp[0].role

        if (!!clientIp) {
            const allSites = await getQuery&lt;{
                server: string,
                value: number,
            }&gt;(
                db,
                `SELECT server_name AS server, COUNT(*) AS value
                FROM ssl
                WHERE server IS NOT NULL AND
                "id.orig_h" = ? AND
                ts &gt;= ? AND ts &lt;= ?
                GROUP BY server;`,
                [clientIp, timeStart, timeEnd]
            )

            if (clientRole === 'node') {
                const clientDependResp = await getQuery&lt;{
                    id: number
                }&gt;(
                    db,
                    'SELECT admin_id as id FROM node_depends WHERE node_id = ?',
                    [clientId]
                )

                adminId = clientDependResp[0].id
            }

            const blacklistStrResp = await getQuery&lt;{
                domains: string
            }&gt;(
                db,
                'SELECT domains FROM block_domains WHERE clientId = ?',
                [!!adminId ? adminId : clientId]
            )

            let blacklistStr: string = blacklistStrResp.reduce((acc, cur) =&gt; acc + ',' + cur.domains, '')

            const blockedDomains = blacklistStr
                    ? blacklistStr.split(',').map(d =&gt; d.trim().toLowerCase()).filter(Boolean)
                    : [];

            const enriched = allSites.map(site =&gt; {
                    const serverLower = site.server.toLowerCase();
                    const inBlacklist = blockedDomains.some(domain =&gt; serverLower.includes(domain));
                    return { ...site, blackList: inBlacklist };
                });

            enriched.sort((a, b) =&gt; b.value - a.value);

            const top5 = enriched.slice(0, 5);

            const blockedNotInTop5 = enriched.filter(
                site =&gt; site.blackList && !top5.some(t =&gt; t.server === site.server)
            );

            const result = [...top5, ...blockedNotInTop5];

            db.close()

            res.json({
                success: true,
                info: result
            })
        } else {
            db.close()

            res.json({
                success: true,
                info: []
            })
        }
    } catch (e) {
        db.close()

        res.json({
            success: false,
            info: 'Произошла непредвиденная ошибка'
        })
    }
}
